  if (!m) return P
  const mob = m.mobility || {}
  return { ...P, class: m.class ?? P.class, mobility: mob.base ?? P.mobility, handling: mob.handling ?? P.handling, speed: mob.speed ?? P.speed, target: m.target }
}
